const NOW = new Date().toISOString();

/** Simplified tryout shape for seed data (no id — auto-generated by DB). */
export interface TryoutInput {
  name: string;
  isTrial: boolean;
  sortOrder: number;
  durationMin: number;
  questions: QuestionInput[];
  createdAt: string;
  updatedAt: string;
}

/**
 * Deterministic seeded shuffle (Fisher-Yates with simple LCG).
 * Produces the same shuffle for the same seed — no randomness at runtime.
 */
function seededShuffle<T>(arr: readonly T[], seed: number): T[] {
  const result = [...arr];
  let s = seed;
  const next = () => {
    s = (s * 1664525 + 1013904223) & 0x7fffffff;
    return s / 0x7fffffff;
  };
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(next() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

/** Generate a derived question set by shuffling base questions and offsetting IDs. */
function deriveSet(base: readonly QuestionInput[], idOffset: number, seed: number): QuestionInput[] {
  return seededShuffle(base, seed).map((q, i) => ({
    ...q,
    id: idOffset + i + 1,
  }));
}

/** Build a TryoutInput object from questions (no explicit id — auto-generated by DB). */
function makeTryout(name: string, questions: QuestionInput[], isTrial = false, sortOrder = 0): TryoutInput {
  return {
    name,
    isTrial,
    sortOrder,
    durationMin: isTrial ? 15 : 100,
    questions,
    createdAt: NOW,
    updatedAt: NOW,
  };
}

